# Auto-synthesised skill: auto_open_notepad_file
# Generated by VN-MateAI MetaArchitect.
# Yêu cầu gốc: Mở file văn bản trên màn hình desktop bằng phần mềm Notepad của Windows

import subprocess
import os
import glob
from typing import Any, Dict, Optional
from core.plugin_manager import export_skill


TEXT_EXTENSIONS = (
    "*.txt", "*.log", "*.csv", "*.md", "*.ini", "*.cfg", "*.conf",
    "*.xml", "*.json", "*.yaml", "*.yml", "*.html", "*.htm", "*.css",
    "*.js", "*.py", "*.bat", "*.cmd", "*.ps1", "*.sh", "*.sql",
    "*.rtf", "*.tex", "*.rst", "*.toml", "*.env", "*.gitignore",
    "*.properties", "*.reg", "*.inf", "*.nfo",
)


@export_skill(
    name="open_text_file_notepad",
    description=(
        "Mở file văn bản trên Desktop bằng Notepad của Windows. Tìm file văn bản trên màn hình desktop rồi mở bằng Notepad. Hỗ trợ nhiều định dạng: txt, log, csv, md, json, xml, py, html, v.v. Người dùng có thể nói: 1) 'mở file văn bản trên desktop bằng notepad' 2) 'mở file txt trên màn hình desktop' 3) 'dùng notepad mở file trên desktop' 4) 'open text file on desktop with notepad' 5) 'mở notepad với file trên desktop' Ví dụ yêu cầu: «Mở file văn bản trên màn hình desktop bằng phần mềm Notepad của Windows»."
    ),
    parameters_schema={
        "type": "object",
        "properties": {
            "filename": {
                "type": "string",
                "description": "Tên file cụ thể cần mở (tuỳ chọn). Nếu không truyền, sẽ tìm và mở file văn bản đầu tiên trên Desktop."
            }
        },
        "required": []
    },
    needs_desktop=True,  # mở cửa sổ Notepad: cần phiên Windows đang đăng nhập (máy chủ Start.bat hoặc máy trạm có Agent)
)
def open_text_file_notepad(filename: Optional[str] = None) -> Dict[str, Any]:
    """Mở file văn bản trên Desktop bằng Notepad."""
    if os.name != "nt":
        return _error("Notepad chỉ có trên Windows — chọn máy trạm Windows (target_client).")
    try:
        desktop_paths = _get_desktop_paths()

        if not desktop_paths:
            return _error("Không tìm thấy thư mục Desktop.")

        if filename:
            # Chỉ tên tệp nằm trên Desktop: "..\..\x" hay "C:\x" không được mở tệp ngoài Desktop.
            name = os.path.basename(str(filename).replace("\\", "/"))
            if not name or name in (".", ".."):
                return _error(f"Tên file không hợp lệ: {filename!r}.")
            file_path = _find_specific_file(desktop_paths, name)
            if file_path is None:
                return _error(f"Không tìm thấy file '{name}' trên Desktop.")
        else:
            file_path = _find_any_text_file(desktop_paths)
            if file_path is None:
                return _error("Không tìm thấy file văn bản nào trên Desktop.")

        return _open_with_notepad(file_path)

    except Exception as e:
        return _error(f"Lỗi khi mở file văn bản bằng Notepad: {str(e)}")


def _error(message: str) -> Dict[str, Any]:
    return {"status": "error", "success": False, "error": message, "message": message}


def _get_desktop_paths() -> list:
    """Lấy danh sách đường dẫn Desktop có thể có."""
    paths = []

    user_profile = os.environ.get("USERPROFILE", "")
    if user_profile:
        user_desktop = os.path.join(user_profile, "Desktop")
        if os.path.isdir(user_desktop):
            paths.append(user_desktop)

    public_profile = os.environ.get("PUBLIC", "")
    if public_profile:
        public_desktop = os.path.join(public_profile, "Desktop")
        if os.path.isdir(public_desktop):
            paths.append(public_desktop)

    onedrive = os.environ.get("OneDrive", "")
    if onedrive:
        onedrive_desktop = os.path.join(onedrive, "Desktop")
        if os.path.isdir(onedrive_desktop):
            paths.append(onedrive_desktop)

    onedrive_consumer = os.environ.get("OneDriveConsumer", "")
    if onedrive_consumer:
        od_consumer_desktop = os.path.join(onedrive_consumer, "Desktop")
        if os.path.isdir(od_consumer_desktop) and od_consumer_desktop not in paths:
            paths.append(od_consumer_desktop)

    onedrive_commercial = os.environ.get("OneDriveCommercial", "")
    if onedrive_commercial:
        od_commercial_desktop = os.path.join(onedrive_commercial, "Desktop")
        if os.path.isdir(od_commercial_desktop) and od_commercial_desktop not in paths:
            paths.append(od_commercial_desktop)

    return paths


def _find_specific_file(desktop_paths: list, filename: str) -> Optional[str]:
    """Tìm file cụ thể theo tên trên Desktop."""
    for desktop in desktop_paths:
        exact_path = os.path.join(desktop, filename)
        if os.path.isfile(exact_path):
            return exact_path

    filename_lower = filename.lower()
    for desktop in desktop_paths:
        try:
            entries = os.listdir(desktop)
        except OSError:
            continue
        for entry in entries:
            if entry.lower() == filename_lower:
                full_path = os.path.join(desktop, entry)
                if os.path.isfile(full_path):
                    return full_path

    for desktop in desktop_paths:
        try:
            entries = os.listdir(desktop)
        except OSError:
            continue
        for entry in entries:
            if filename_lower in entry.lower():
                full_path = os.path.join(desktop, entry)
                if os.path.isfile(full_path):
                    return full_path

    return None


def _find_any_text_file(desktop_paths: list) -> Optional[str]:
    """Tìm file văn bản đầu tiên trên Desktop."""
    all_files: list = []

    for desktop in desktop_paths:
        for pattern in TEXT_EXTENSIONS:
            matched = glob.glob(os.path.join(desktop, pattern))
            for f in matched:
                if os.path.isfile(f) and f not in all_files:
                    all_files.append(f)

    if not all_files:
        return None

    all_files.sort(key=lambda f: os.path.getmtime(f), reverse=True)
    return all_files[0]


def _open_with_notepad(file_path: str) -> Dict[str, Any]:
    """Mở file bằng Notepad."""
    try:
        subprocess.Popen(
            ["notepad.exe", file_path],
            creationflags=0x00000008,
        )
        basename = os.path.basename(file_path)
        return {"status": "success", "success": True, "file": basename,
                "message": f"Đã mở file '{basename}' bằng Notepad thành công."}
    except FileNotFoundError:
        return _error("Không tìm thấy notepad.exe trên hệ thống.")
    except OSError as e:
        return _error(f"Lỗi khi khởi chạy Notepad: {str(e)}")
